י. עִקַּר הַקִּלְקוּל הָרִאשׁוֹן הִתְחִיל מֵעֵצוֹת רָעוֹת שֶׁהֵם עֲצַת הַנָּחָשׁ הַקַּדְמוֹנִי כְּמוֹ שֶׁנֶּאֱמַר הַנָּחָשׁ הִשִׁיאָנִי. וּמֵאָז נִתְקַלְקֵל הָעֵצָה. וְכָל הַחֻרְבָּנוֹת וְהַגָּלֻיּוֹת וַחֲלוּקַת מַלְכוּת בֵּית דָּוִד וְכָל הַצָּרוֹת רַחֲמָנָא לִצְּלָן שֶׁעָבְרוּ עַל יִשְׂרָאֵל הַכֹּל עַל יְדֵי פְּגַם הָעֵצָה וְכַמְּבֹאָר בִּפְנִים, וְעִקַּר תִּקּוּן הָעֵצָה הִתְחִיל מֵאַבְרָהָם אָבִינוּ שֶׁמִּמֶּנּוּ הִתְחִיל הַמְשָׁכַת הַתּוֹרָה בָּעוֹלָם שֶׁנִּקְרֵאת עֵצָה וְתוּשִׁיָּה. וְעַל כֵּן זָכָה אַבְרָהָם שֶׁנִּקְרָא יוֹעֵץ לְהַקָּדוֹשׁ בָּרוּךְ הוּא כִּבְיָכוֹל, כְּמוֹ שֶׁכָּתוּב אֶת מִי נוֹעַץ וַיְבִינֵהוּ וּכְתִיב וְאִישׁ עֲצָתוֹ יוֹדִיעֶנּוּ. וְכֵן כָּל הַצַּדִּיקִים נִקְרָאִים יוֹעֲצִים לְהַשֵּׁם יִתְבָּרַךְ. וְעִקַּר גְּמַר תִּקּוּן הָעֵצָה בִּשְׁלֵמוּת יִהְיֶה כְּשֶׁיָּבוֹא מָשִׁיחַ. וְעַל־כֵּן אָז יַחֲזֹר וְיִתְאַחֵד גַּם מַלְכוּת בֵּית דָּוִד, כְּמוֹ שֶׁכָּתוּב: וְלֹא יֵחָצוּ לִשְׁתֵּי מַמְלָכוֹת עוֹד. כִּי מָשִׁיחַ נִקְרָא פֶּלֶא יוֹעֵץ וּכְתִיב בֵּיהּ וְנָחָה עָלָיו וְכוּ' רוּחַ עֵצָה וְכוּ' (שם ב ז יא). 
יא. יָדוּעַ מַאֲמַר רַבּוֹתֵינוּ זַ"ל בַּדֶּרֶךְ שֶׁאָדָם רוֹצֶה לֵילֵךְ מוֹלִיכִין אוֹתוֹ. וּמִזֶּה בָּאִים כָּל הָעֵצוֹת הַמְקֻלְקָלוֹת שֶׁנִּדְמֶה לוֹ כִּי מֵאֵת ה' הֵם אוֹ שֶׁהַצַּדִּיק יָעַץ לוֹ כָּךְ, וּבֶאֱמֶת הַכֹּל מִמֶּנּוּ בְּעַצְמוֹ כְּמוֹ שֶׁנֶּאֱמַר אִוֶּלֶת אָדָם תְּסַלֵּף דַּרְכּוֹ וְכוּ'. כִּי כְּמוֹ שֶׁשּׁוֹאֲלִין אֶת הַצַּדִּיק כֵּן הוּא מֵשִׁיב. עַל כֵּן מִי שֶׁרוֹצֶה לָחוּס עַל עַצְמוֹ בֶּאֱמֶת צָרִיךְ לְבַקֵּשׁ מְאֹד בְּתַחֲנוּנִים רַבִּים אֶת הַשֵּׁם יִתְבָּרַךְ וְאֶת הַצַּדִּיקֵי אֱמֶת שֶׁיָּשִׂימוּ לִבָּם הֵיטֵב עַל מַה שֶּׁנַּעֲשָׂה עִמּוֹ, וִירַחֲמוּ עָלָיו בֶּאֱמֶת בְּאֹפֶן שֶׁיִּתְּנוּ לוֹ עֵצָה אֲמִתִּית שֶׁיַּצְלִיחַ עַל יָדָהּ לָנֶצַח בֶּאֱמֶת (שם

). 
כ. עִקַּר תֹּקֶף הַהַעֲלָמָה שֶׁמִּתְגַּבֶּרֶת בָּעוֹלָם הוּא רַק מֵחֲמַת חֶסְרוֹן הָעֵצָה. כִּי בֶּאֱמֶת הַכֹּל יוֹדְעִין שֶׁהָעוֹלָם הַזֶּה צֵל עוֹבֵר כִּי אֵיךְ אֶפְשָׁר לְהַכְחִישׁ זֹאת שֶׁהָאָדָם הַיּוֹם בְּכָאן וּמָחָר בַּקֶּבֶר. אַךְ מִגֹּדֶל תַּאֲווֹת הַגּוּף שֶׁמִּתְגַּבְּרִין בָּעוֹלָם וְאֵין יוֹדְעִים לָתֵת עֵצוֹת בְּנַפְשָׁם, אֵיךְ לְהִנָּצֵל מֵהֶם וּלְמַלֵּט נַפְשָׁם מִנִּי שַׁחַת, מֵחֲמַת זֶה רֹב הָעוֹלָם מְסִיחִים דַּעְתָּם מִזֶּה וּכְרוּכִים אַחַר הַבְלֵי עוֹלָם. כִּי אוֹמְרִים מָה אֶפְשָׁר לָנוּ לַעֲשׂוֹת כִּי כְּבָר נִלְכַּדְנוּ בַּמֶּה שֶׁנִּלְכַּדְנוּ, וְכַיּוֹצֵא בָּזֶה סְבָרוֹת הַרְבֵּה שֶׁל שֶׁקֶר שֶׁאוֹמְרִים הָעוֹלָם. עַל כֵּן עִקַּר הַתִּקּוּן עַל יְדֵי הַצַּדִּיק הָאֱמֶת שֶׁמַּמְשִׁיךְ שֵׂכֶל עֶלְיוֹן וְנִפְלָא מְאֹד, עַד שֶׁמֵּאִיר עֵצוֹת אֲמִתִּיּוֹת וְנִפְלָאוֹת גַּם לְכָל הָעוֹמְדִים בַּחוּץ וְעַל יְדֵי זֶה נִתְגַּלָּה הַהַעֲלָמָה (שם בהראשי פרקים). 
כא. עִקַּר הַמַּלְכוּת הוּא עַל יְדֵי עֵצוֹת. וְעַל כֵּן כָּל מֶלֶךְ יֵשׁ לוֹ יוֹעֲצִים. כִּי עִקַר בִּנְיַן הַמַּלְכוּת הוּא מִבְּחִינַת עֵצוֹת כַּיָּדוּעַ. וְעַל כֵּן עִקַּר חֲלוּקַת מַלְכוּת בֵּית דָּוִד הָיָה עַל יְדֵי פְּגַם הָעֵצוֹת, אֲשֶׁר לֹא רָצָה רְחָבְעָם לִשְׁמֹעַ לַעֲצַת הַזְּקֵנִים וְהָלַךְ אַחַר עֲצַת הַנְּעָרִים. וְעִקַּר קִיּוּם מַלְכוּת יִשְׂרָאֵל הוּא עַל יְדֵי עֵצוֹת דִּקְדֻשָּׁה שֶׁהוּא תַּרְיַ"ג עֵטִין שֶׁהֵם כְּלַל הַתּוֹרָה, וְזֶה שֶׁכָּתוּב אֵצֶל מִצְוַת הַמֶּלֶךְ וְהָיְתָה עִמּוֹ וְקָרָא בּוֹ כָּל יְמֵי חַיָּיו לְמַעַן יַאֲרִיךְ יָמִים עַל מַמְלַכְתּוֹ (הל' הכשר כלים הלכה ב

). 
כח. עִקַּר הָעֵצוֹת שֶׁעַל יָדָם גְּדֵלָה הָאֱמוּנָה נִמְשָׁכִין מֵאֱמֶת (שם). 
כט. צְרִיכִין הַבְחָנָה גְּדוֹלָה לְהַבְחִין בֵּין אוֹר יוֹם שֶׁהוּא בְּחִינַת עֵצוֹת טוֹבוֹת וּבֵין חֶשְׁכַת לַיְלָה שֶׁהוּא בְּחִינַת קִלְקוּל הָעֵצוֹת. כִּי כַּמָּה בְּנֵי אָדָם נִכְשָׁלִין בָּזֶה. כִּי הָעֵצוֹת דִּקְדֻשָּׁה אַף עַל פִּי שֶׁהוּא בְּחִינַת תְּמִימוּת וּפְשִׁיטוּת גָּמוּר כַּמְּבֹאָר בְּמָקוֹם אַחֵר, אַף עַל פִּי כֵן יֵשׁ בָּהֶם עַמְקוּת גָּדוֹל מְאֹד מִבְּחִינַת מַיִם עֲמֻקִּים עֵצָה בְּלֵב אִישׁ. וּצְרִיכִין לְבַקֵּשׁ הַרְבֵּה הַרְבֵּה מֵהַשֵּׁם יִתְבָּרַךְ שֶׁיָּאִיר לוֹ בְּתוֹךְ חֶשְׁכַת אֲפֵלָתוֹ, עַמְקוּת אֲמִתַּת הָעֵצוֹת דִּקְדֻשָּׁה בְּאֹפֶן שֶׁיִּתְחַזֵּק בְּדַרְכֵי עֲבוֹדָתוֹ יִתְבָּרַךְ תָּמִיד. וְזֶה בְּחִינַת הַנּוֹתֵן לַשֶּׂכְוִי בִּינָה לְהַבְחִין בֵּין יוֹם וּבֵין לַיְלָה שֶׁמְּבָרְכִין בַּחֲצוֹת לַיְלָה, כִּי אָז צְרִיכִין עִקַּר הַהַבְחָנָה מֵאֲחַר שֶׁעֲדַיִן הוּא לַיְלָה מַמָּשׁ, וְאַף עַל פִּי כֵן כְּבָר הִתְחִיל לִצְמֹחַ אוֹר הַיּוֹם שֶׁהוּא בְּחִינַת אוֹר הָעֵצוֹת הַקְּדוֹשׁוֹת. כִּי הַשֵּׁם יִתְבָּרַךְ מְרַחֵם עָלֵינוּ וּמֵאִיר לָנוּ גַּם בְּתוֹךְ הַחשֶׁךְ בְּחִינַת הֶאָרַת הָעֵצוֹת הָעֲמֻקּוֹת לְהַצִּיל נַפְשֵׁנוּ מִנִּי שַׁחַת. אֲבָל צְרִיכִין לָזֶה הַבְחָנָה גְּדוֹלָה שֶׁלֹּא יִטְעֶה מִן הָאֱמֶת עַל יְדֵי הַמְּסִיתִים וְהַמְּדִיחִים בַּעֲצוֹת שְׁקָרִים וּבִדְבָרִים לה בְּדוּיִים שֶׁאֵינָם עַל פִּי תּוֹרָתֵנוּ הַקְּדוֹשָׁה כְּלָל. וּמִי שֶׁחָפֵץ בֶּאֱמֶת לַאֲמִתּוֹ וּמִתְעוֹרֵר לָקוּם לַעֲבוֹדַת הַשֵּׁם יִתְבָּרַךְ זוֹכֶה לִשְׁמֹעַ קוֹל הַכָּרוֹז שֶׁל הַתּוֹרָה הַקְּדוֹשָׁה. שֶׁמִּשָּׁם נִמְשָׁךְ וּמִשְׁתַּלְשֵׁל קוֹל הַתַּרְנְגֹל שֶׁמְּעוֹרֵר אֶת הָאָדָם בַּחֲצוֹת לַיְלָה לָקוּם וּלְהִתְעוֹרֵר מִשְּׁנָתוֹ, וְעַל יְדֵי זֶה זוֹכֶה לְהַבְחִין בֵּין יוֹם וּבֵין לַיְלָה, דְּהַיְנוּ בֵּין עֵצוֹת טוֹבוֹת אֶל הַהֵפֶךְ חַס וְשָׁלוֹם שֶׁהוּא תָּלוּי בִּנְקֻדָּה בְּעָלְמָא וּבְחוּט הַשְּׂעָרָה. וְזֶה בְּחִינַת מִי שָׁת בְּטוּחוֹת חָכְמָה, הַיְנוּ בְּחִינַת הָעֵצוֹת הַקְּדוֹשׁוֹת שֶׁהֵם בְּחִינַת טוּחוֹת וּכְלָיוֹת כִּי כְּלָיוֹת יוֹעֲצוֹת. וְזֶה שֶׁסִּיֵּם אוֹ מִי נָתַן לַשֶּׂכְוִי בִינָה. 'וְשֶׂכְוִי' פֵּרֵשׁ רַשִּׁ"י 'זֶה הַלֵּב', דָּבָר אַחֵר זֶה תַּרְנְגֹל וְכוּ', כִּי צְרִיכִין לְהַטּוֹת אָזְנוֹ הֵיטֵב לִשְׁמֹעַ קוֹל הַכָּרוֹז הַנַּ"ל וּלְהִתְעוֹרֵר עַל יָדוֹ, עַד שֶׁעַל יְדֵי זֶה מַבְחִין הַלֵּב בֵּין יוֹם לְלַיְלָה, בֵּין עֵצוֹת טוֹבוֹת אֲמִתִּיּוֹת לְהַהֵפֶךְ חַס וְשָׁלוֹם כַּנַּ"ל (עיין פנים שם

). 
מ. הַמִּנְעָלִים דִּקְדֻשָּׁה הַנַּ"ל נִמְשָׁכִין מִבְּחִינַת אוֹר הַתְּפִלִּין וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל כַּתְּפִלִּין כָּךְ מִנְעָלִים. וּתְפִלִּין הֵם בְּחִינַת אֱמֶת כַּמְּבֹאָר בְּמָקוֹם אַחֵר, כִּי הָעֵצוֹת שֶׁהֵם בְּחִינַת רַגְלִין הֵם בְּחִינַת דֶּרֶךְ שֶׁנַּעֲשָׂה עַל יְדֵי הָרַגְלִין. כִּי כְּשֶׁיּוֹדֵעַ הָעֵצָה אֵיךְ לְהִתְנַהֵג זֶה בְּחִינַת שֶׁיּוֹדֵעַ הַדֶּרֶךְ לֵילֵךְ בּוֹ. וְעַל כֵּן כָּל הַתּוֹרָה שֶׁהִיא בְּחִינַת עֵצוֹת נִקְרֵאת דֶּרֶךְ כַּמְּבֹאָר בִּפְסוּקִים הַרְבֵּה. וּכְשֶׁאֵינוֹ יוֹדֵעַ הָעֵצָה אֵיךְ לְהִתְנַהֵג וְעֵצָה חֲלוּקָה אֶצְלוֹ זֶה בְּחִינַת שֶׁאֵינוֹ יוֹדֵעַ בְּאֵיזֶה דֶּרֶךְ הוּא מְהַלֵּךְ. וְעַל זֶה בִּקֵּשׁ דָּוִד הַמֶּלֶךְ עָלָיו הַשָּׁלוֹם הוֹדִיעֵנִי דֶּרֶךְ זוּ אֵלֵךְ. הַדְרִיכֵנִי בִּנְתִיב מִצְווֹתֶיךָ וְכוּ'. וְעִקַּר תִּקּוּן שְׁלֵמוּת הָעֵצָה לֵידַע בְּאֵיזֶה דֶּרֶךְ לֵילֵךְ הוּא עַל יְדֵי אֱמֶת, כִּי הָאֱמֶת הוּא אֶחָד. וְצָרִיךְ כָּל אָדָם כְּשֶׁמְּסֻפָּק בְּאֵיזֶה דֶּרֶךְ וְהַנְהָגָה וְאֵינוֹ יוֹדֵעַ לָשִׁית עֵצוֹת בְּנַפְשׁוֹ, עִקַּר תַּקָּנָתוֹ הוּא הָאֱמֶת שֶׁיִּרְאֶה לִמְשֹׁךְ עַצְמוֹ רַק אֶל הָאֱמֶת לַאֲמִתּוֹ. וּלְהִסְתַּכֵּל רַק עַל הָאֱמֶת וּלְבַקֵּשׁ מֵהַשֵּׁם יִתְבָּרַךְ שֶׁיּוֹלִיכֵהוּ וְיַדְרִיכֵהוּ בְּדֶרֶךְ הָאֱמֶת, כְּמוֹ שֶׁנֶּאֱמַר: "הַדְרִיכֵנִי בַּאֲמִתֶּךָ וְלַמְּדֵנִי" וְכוּ'. וּכְמוֹ שֶׁנֶּאֱמַר: "הוֹרֵנִי ה' דַּרְכְּךָ אַהֲלֵךְ בַּאֲמִתֶּךָ". וּכְתִיב: "שְׁלַח אוֹרְךָ וַאֲמִתְּךָ הֵמָּה יַנְחוּנִי" וְכוּ'. וְעַל יְדֵי אוֹר הָאֱמֶת זוֹכֶה לְעֵצָה שְׁלֵמָה. אַךְ כְּדֵי שֶׁלֹּא יִתְגַּבְּרוּ הַקְּלִפּוֹת בְּכָל פַּעַם לְהִתְאַחֵז חַס וְשָׁלוֹם בְּהָרַגְלִין שֶׁהֵם בְּחִינַת עֵצוֹת וּלְבַלְבֵּל הָעֵצָה בְּכָל פַּעַם, עַל כֵּן נִמְשָׁךְ מִבְּחִינַת אוֹר הָאֱמֶת בְּחִינַת הַמִּנְעָלִים שֶׁהֵם שְׁמִירָה לָרַגְלִין שֶׁהֵם נוֹעֲלִין וְסוֹגְרִין הָעֵצָה דִּקְדֻשָּׁה שֶׁלֹּא יִגַּע בָּהּ זָר לְבַלְבְּלָהּ וּלְחַלְּקָהּ חַס וְשָׁלוֹם. כִּי הַמִּנְעָלִים נִמְשָׁכִים מֵאוֹר הָאֱמֶת מִבְּחִינַת תְּפִלִּין שֶׁזֶּה בְּחִינַת הַחַשְׁמַל, שֶׁנִּמְשָׁךְ מִבְּחִינַת אוֹר הָאֱמֶת שֶׁבַּלֵּב. וּלְמַטָּה בָּרַגְלִין נִתְגַּשֵׁם לְבוּשׁ הַחַשְׁמַל בִּבְחִינַת מִנְעָלִים כַּיָּדוּעַ (שם). 
מא. לִפְעָמִים נוֹפֵל הָאָדָם לִסְפֵקוֹת וְעֵצוֹת חֲלוּקוֹת כָּל כָּךְ עַד שֶׁאִי אֶפְשָׁר לוֹ בְּשׁוּם אֹפֶן לֵידַע הָאֱמֶת אֵיךְ לְהִתְנַהֵג. וְכָל מַה שֶּׁחוֹתֵר לִמְצֹא עֵצָה שְׁלֵמָה מְבַלְבְּלִין עֲצָתוֹ בְּכָל פַּעַם. כִּי עַכְשָׁו נִגְמַר בְּדַעְתּוֹ בִּרְאָיוֹת בְּרוּרוֹת שֶׁהוּא צָרִיךְ לְהִתְנַהֵג כָּךְ, וּבְתוֹךְ כָּךְ עוֹלֶה עַל דַּעְתּוֹ סְבָרָא אַחֶרֶת עַד שֶׁעֲצָתוֹ הָרִאשׁוֹנָה נִסְתֶּרֶת לְגַמְרֵי וְעוֹלִים סְבָרוֹת בְּדַעְתּוֹ שֶׁצָּרִיךְ לְהִתְנַהֵג בְּהִפּוּךְ מַמָּשׁ מִמַּה שֶּׁחָשַׁב מִקֹּדֶם, וְזֶה בְּחִינַת עֵצוֹת חֲלוּקוֹת הַנַּ"ל. וְלִפְעָמִים מִתְגַּבֵּר חֲלוּקַת הָעֵצָה כָּל כָּךְ עַד שֶׁאֵינוֹ יוֹדֵעַ בְּשׁוּם אֹפֶן לְהַכְרִיעַ הָעֵצָה לְכָאן אוֹ לְכָאן. וּכְשֶׁהָאָדָם רוֹאֶה בְּעַצְמוֹ שֶׁהוּא מֻנָּח בַּחשֶׁךְ זֶה זְמַן רַב, וְאֵינוֹ יוֹדֵעַ שׁוּם עֵצָה לָצֵאת מִמַּה שֶׁצָּרִיךְ לָצֵאת, וַעֲצָתוֹ חֲלוּקָה מְאֹד חַס וְשָׁלוֹם, אֲזַי זֶהוּ בְּעַצְמוֹ תַּקָּנָתוֹ שֶׁיִּצְעַק עַל זֶה בְּעַצְמוֹ לְהַשֵּׁם יִתְבָּרַךְ עַל אֲשֶׁר נָפַל כָּל כָּךְ עַד שֶׁאֵינוֹ יוֹדֵעַ הָעֵצָה שְׁלֵמָה אֵיךְ לָצֵאת מֵחשֶׁךְ לְאוֹר. כִּי בְּוַדַּאי אֵין שׁוּם יֵאוּשׁ בָּעוֹלָם כְּלָל, וּבְוַדַּאי גַּם בִּמְקוֹמוֹ נִמְצָאִין עֵצוֹת אֵיךְ לָצֵאת מֵחשֶׁךְ לְאוֹר, מֵרָע לְטוֹב. רַק שֶׁבַּעֲו?ֹנוֹתָיו נֶעֶלְמוּ מִמֶּנּוּ הָעֵצוֹת בִּבְחִינַת מִי זֶה מַחֲשִׁיךְ עֵצָה בְּמִלִּין וְכוּ'. וְעַל כֵּן תַּקָּנָתוֹ שֶׁיֵּדַע עַל כָּל פָּנִים הָאֱמֶת שֶׁנָּפַל כָּל כָּךְ וְנִתְרַחֵק כָּל כָּךְ עַד שֶׁאֵינוֹ יוֹדֵעַ שׁוּם עֵצָה, וְיִצְעַק עַל זֶה בְּעַצְמוֹ לְהַשֵּׁם יִתְבָּרַךְ שֶׁיּוֹרֵהוּ הָעֵצָה וְהַדֶּרֶךְ אֵיךְ לְהִתְנַהֵג בֶּאֱמֶת. וּכְמוֹ שֶׁדָּוִד הַמֶּלֶךְ עָלָיו הַשָּׁלוֹם צָעַק עַל זֶה הַרְבֵּה. כִּי בֶּאֱמֶת גַּם עַל הַצַּדִּיקִים הַגְּדוֹלִים בְּמַעֲלָה מְאֹד עוֹבְרִים עֲלֵיהֶם גַּם כֵּן עֵצוֹת חֲלוּקוֹת בְּעִנְיְנֵיהֶם וּבְהַנְהָגוֹתֵיהֶם, וְכַמּוּבָן מִמַּה שֶּׁצָּעַק דָּוִד הַמֶּלֶךְ עָלָיו הַשָּׁלוֹם עַד אָנָּה אָשִׁית עֵצוֹת בְּנַפְשִׁי וְכוּ', שֶׁמּוּבָן מִזֶּה שֶׁעָבַר עָלָיו חֲלוּקוֹת הָעֵצָה הַרְבֵּה מְאֹד. מִכָּל שֶׁכֵּן וְכָל שֶׁכֵּן קְטַנֵּי הָעֵרֶךְ. מִכָּל שֶׁכֵּן הַנִּלְכָּדִים בְּמַאֲסַר הַתַּאֲווֹת וּבְהִרְהוּרִים וְכוּ' וְכוּ' רַחֲמָנָא לִצְּלָן. שֶׁצְּרִיכִין לֵידַע וּלְהַאֲמִין שֶׁבְּוַדַּאי בְּכָל מָקוֹם שֶׁהֵם יֵשׁ שָׁם עֵצָה וְתַחְבּוּלָה אֵיךְ לָצֵאת וְלָשׁוּב מִשָּׁם, אַךְ שֶׁאֵין יוֹדְעִין הָעֵצָה וַעֲצָתָם חֲלוּקָה תָּמִיד. עַל כֵּן תַּקָּנָתָם שֶׁיֵּדְעוּ הָאֱמֶת שֶׁאֵין יוֹדְעִים שׁוּם עֵצָה, וְיִתְפַּלְּלוּ עַל זֶה הַרְבֵּה לְהַשֵּׁם יִתְבָּרַךְ, וְאָז יְכוֹלִין לִזְכּוֹת שֶׁתִּהְיֶה הַיְרִידָה תַּכְלִית הָעֲלִיָּה כַּמְּבֹאָר בִּפְנִים שָׁם אוֹת כה (ועיין בין המצרים

). 
יח. בְּכָל דּוֹר וָדוֹר יֵשׁ כַּמָּה צַדִּיקִים אֲמִתִּיִּים. אֲבָל יֵשׁ אֱמֶת לְמַעְלָה מֵאֱמֶת כִּי בְּוַדַּאי אֵין מַדְרֵגַת כָּל הַצַּדִּיקִים שָׁוִין. וְכָל מַה שֶּׁמַּעֲלַת וּמַדְרֵגַת הַצַּדִּיק גָּדוֹל יוֹתֵר בְּוַדַּאי הָאֱמֶת שֶׁלּוֹ גָּדוֹל וּמְבֻרָר בְּיוֹתֵר. כִּי הָעִקָּר הוּא הָאֱמֶת. עַד שֶׁיֵּשׁ בְּכָל דּוֹר צַדִּיק אֲמִתִּי שֶׁהוּא בְּחִינַת נְקֻדַּת הָאֱמֶת שֶׁבֵּין הַצַּדִּיקִים, רַק מֵחֲמַת הִתְגַּבְּרוּת הַחִלּוּפִים וְהַתְּמוּרוֹת עַל יְדֵי זֶה קָשֶׁה מְאֹד לֵידַע הֵיכָן הָאֱמֶת. כִּי עַל פִּי רֹב מִתְגָּרֶה הַבַּעַל דָּבָר בְּהַצַּדִּיקִים בְּעַצְמָן, וּמַכְנִיס בֵּינֵיהֶם מַחֲלֹקֶת גָּדוֹל לַחֲלֹק עַל זֶה הַצַּדִּיק הָאֱמֶת, שֶׁהוּא בְּחִינַת נְקֻדַּת הָאֱמֶת שֶׁבֵּין הַצַּדִּיקִים, וְנִדְמֶה לָהֶם כְּאִלּוּ זֶה הַצַּדִּיק דַּיְקָא נוֹטֶה חַס וְשָׁלוֹם מִדֶּרֶךְ הָאֱמֶת. וּמִזֶּה הָיָה בְּחִינַת הַמַּחֲלֹקֶת שֶׁחָלְקוּ הַשְּׁבָטִים עַל יוֹסֵף עַד אֲשֶׁר לְעֶבֶד נִמְכַּר יוֹסֵף. וְעַל יְדֵי זֶה נִתְגַּלְגֵּל הַדָּבָר וְיָרְדוּ אֲבוֹתֵינוּ לְמִצְרַיִם וְהָיוּ שָׁם עֲבָדִים. וְכֵן מַחֲלֹקֶת שָׁאוּל שֶׁרָדַף אֶת דָּוִד בְּחִנָּם, וּכְמוֹ שֶׁמָּצִינוּ בְּכַמָּה וְכַמָּה דּוֹרוֹת בִּפְרָט בַּדּוֹרוֹת הַלָּלוּ בְּעִקְבוֹת מְשִׁיחָא שֶׁהִתְגַּבֵּר הַקַּטֵיגוֹרְיָא וְהַמַּחֲלֹקֶת גַּם בֵּין הַצַּדִּיקִים, עַד שֶׁאֵין יוֹדְעִין הֵיכָן הָאֱמֶת. עַל כֵּן צְרִיכִין לְהִתְפַּלֵּל לְהַשֵּׁם יִתְבָּרַךְ עַל זֶה הַרְבֵּה כַּנַּ"ל (שם יז). 
יט. כָּל יִשְׂרָאֵל כְּלוּלִים בְּמשֶׁה שֶׁהוּא בְּחִינַת הַצַּדִּיק הָאֱמֶת שֶׁבְּכָל דּוֹר, שֶׁהוּא כָּלוּל מִנִּשְׁמוֹת יִשְׂרָאֵל, כִּי אִתְפַּשְׁטוּתָא דְּמשֶׁה בְּכָל דָּרָא וְדָרָא. וּבְכָל אֶחָד מִיִּשְׂרָאֵל יֵשׁ בְּחִינַת נְקֻדָּה טוֹבָה שֶׁהִיא בְּחִינַת משֶׁה, כִּי משֶׁה רַבֵּנוּ עָלָיו הַשָּׁלוֹם מְלֻבָּשׁ אֵצֶל כָּל אֶחָד מִיִּשְׂרָאֵל בְּכָל אֵבָר וְאֵבָר. וְזֹאת הַנְּקֻדָּה בְּחִינַת משֶׁה שֶׁמְּלֻבָּשׁ אֵצֶל כָּל אֶחָד הִיא עוֹמֶדֶת בֵּין שְׁמַד לְרָצוֹן, הַיְנוּ בֵּין הַסִּטְרָא אָחֳרָא וּבֵין הַקְּדֻשָּׁה. וְעַל יְדֵי זֶה כָּל כֹּחוֹ לְהִתְגַּבֵּר לָצֵאת בְּכָל פַּעַם מֵרָע לְטוֹב שֶׁהוּא בְּחִינַת מִשְּׁמַד לְרָצוֹן. וְעַל כֵּן בֶּאֱמֶת כָּל עִקַּר קְדֻשַּׁת אִישׁ הַיִּשְׂרְאֵלִי הוּא עַל יְדֵי הִתְקָרְבוּת לְצַדִּיקֵי אֱמֶת, שֶׁהֵם בְּחִינַת משֶׁה, שֶׁהוּא כָּלוּל מִכָּל יִשְׂרָאֵל וְעוֹמֵד בֵּין שְׁמַד לְרָצוֹן, לְהַעֲלוֹת הַנְּפָשׁוֹת מֵרָע לְטוֹב מִשְּׁמַד לְרָצוֹן. כִּי הַסַּכָּנָה שֶׁבְּזֶה הָעוֹלָם הִיא עֲצוּמָה מְאֹד, וּבֵין הַקְּדֻשָּׁה וְהַסִּטְרָא אָחֳרָא הוּא רַק כְּחוּטָא דָּקִיק, וּבְקַל יוּכַל לְהִלָּכֵד בָּהּ חַס וְשָׁלוֹם בְּחִינַת כְּפֶשַׂע בֵּינִי וּבֵין הַמָּוֶת, וּכְמַאֲמַר רַבּוֹתֵינוּ זַ"ל, בְּכָל יוֹם יִצְרוֹ שֶׁל אָדָם מִתְגַּבֵּר עָלָיו. וְעִקַּר הַכֹּחַ לְהִנָּצֵל מִכָּל זֶה הוּא רַק עַל יְדֵי הַצַּדִּיק בְּחִינַת משֶׁה, שֶׁעוֹמֵד וּמַעֲלֶה בְּכָל עֵת מִשְּׁמַד לְרָצוֹן (שם הלכה ה
